model:
rachana: 1
sutra: sa-ccr
version: 1
description: 
match: { kind: sa-ccr, priority: 10 }
title: { pill: "Exposure and capital · SA-CCR exposure", id: "$.CALC_ID" }
strip:
  - { label: "RC", bind: "$.REPLACEMENT_COST", fmt: "compact" }
  - { label: "Add-on", bind: "$.ADD_ON", fmt: "compact" }
  - { label: "Multiplier", bind: "$.MULTIPLIER", fmt: "df4" }
  - { label: "EAD", bind: "$.EAD", fmt: "compact", emphasis: true }
  - { label: "RWA", bind: "$.RWA", fmt: "compact" }
panels:
  - id: addons
    kind: hbar
    title: "Add-on by asset class"
    key: "F2"
    phone: { tier: "glance", from: "fragment", rows: 5 }
    rows: "$.ADD_ONS"
    label: "ASSET_CLASS"
    value: "ADD_ON"
    fmt: "compact"
  - id: hedging
    kind: table
    title: "Hedging sets"
    rows: "$.HEDGING_SETS"
    columns:
      - { label: "Asset class", bind: "@.ASSET_CLASS" }
      - { label: "Hedging set", bind: "@.HEDGING_SET" }
      - { label: "Effective notional", bind: "@.EFFECTIVE_NOTIONAL", fmt: "compact" }
      - { label: "SF", bind: "@.SF", fmt: "pct2" }
  - id: checks
    kind: kv
    title: "Checks: the EAD identity"
    area: right
    columns:
      - { label: "EAD (check: alpha × (RC + multiplier × add-on))", bind: "$.ALPHA * ($.REPLACEMENT_COST + $.MULTIPLIER * $.ADD_ON)", fmt: "compact" }
      - { label: "EAD difference", bind: "$.ALPHA * ($.REPLACEMENT_COST + $.MULTIPLIER * $.ADD_ON) - $.EAD", fmt: "signed0", tone: "sign" }
      - { label: "Add-on (check: sum by asset class)", bind: "sum($.ADD_ONS, 'ADD_ON')", fmt: "compact" }
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
  - id: refs
    kind: links
    title: "Linked entities"
    code: "REFS"
    area: right
    phone: { tier: "more", from: "fragment" }
keys: { F7: "link($.NETTING_SET, 'netting-set')", F8: "impact", F9: "raw" }
